import {id,normalize,goals,sessionVolume,validate} from './domain.js';
import {methods,prescription,validatePrescription,createWeeks,applyWeek,performance,muscleVolume,studentBundle,mergeStudentFeedback} from './beta-domain.js';
import {exportBackup,importBackup} from './backup.js';
let C,studentId='',exerciseId='',month=new Date().toISOString().slice(0,7),selectedPlan='',feedbackPacket=null;
export function initBeta(ctx){C=ctx;}
const state=()=>C.state(), E=x=>C.esc(x),B=(label,cmd,style='secondary',attrs='')=>C.button(label,'b:'+cmd,style,attrs),I=(...x)=>C.input(...x),S=(...x)=>C.select(...x),T=(...x)=>C.textarea(...x),fmt=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(n),money=n=>state().advanced.preferences.hideMoney?'••••':new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n/100);
const attrs=id=>`data-id="${E(id)}"`;
const studentOptions=(personal=true)=>[...(personal?[['','Treino pessoal']]:[]),...state().students.map(s=>[s.id,`${s.name}${s.active?'':' (inativo)'}`])];
const header=(title,description,action='')=>`<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;
const chooseStudent=()=>`<form data-kind="b:filter" class="toolbar">${S('studentId','Aluno',studentOptions(),studentId)}<button class="secondary" type="submit">Selecionar</button></form>`;
const card=(title,body)=>`<section class="panel"><h2>${title}</h2>${body}</section>`;
const empty=text=>`<p class="note">${text}</p>`;
function studentRequired(){if(!state().students.length)throw new Error('Cadastre um aluno antes de continuar.');}
export function modules(){const list=[['Agenda','agenda','Sessões, faltas e lembretes'],['Avaliações','assessments','Medidas, fotos e hábitos'],['Planejamento','planning','Mesociclos, deload e semanas'],['Volume e recuperação','muscle','Séries diretas e indiretas'],['Análise e progressão','analysis','Histórico, gráficos e sugestões'],['Comunicação','messages','Mensagens e feedback por aluno'],['Gestão profissional','finance','Mensalidades e relatórios'],['Qualidade e biblioteca','quality','Catálogo e revisão de mídias']];C.modal('Módulos do EvoluPersonal',`<div class="cards">${list.map(([label,view,desc])=>`<article class="card"><h3>${label}</h3><p>${desc}</p>${B('Abrir','view','primary',`data-view="${view}"`)}</article>`).join('')}</div>`);}
function agenda(){const a=state().advanced.appointments.filter(x=>new Date(x.at).toISOString().slice(0,7)===month&&(!studentId||x.studentId===studentId)).sort((a,b)=>a.at-b.at);const [year,m]=month.split('-').map(Number),days=new Date(year,m,0).getDate(),first=(new Date(year,m-1,1).getDay()+6)%7;return header('Agenda e calendário','Planeje sessões e acompanhe presença.',B('Novo compromisso','new-appointment','primary'))+chooseStudent()+`<form data-kind="b:month" class="toolbar">${I('month','Mês',month,'month','required')}<button class="secondary">Mostrar</button></form><div class="calendar-grid">${['SEG','TER','QUA','QUI','SEX','SÁB','DOM'].map(x=>`<small>${x}</small>`).join('')}${Array.from({length:first},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>{const n=a.filter(x=>new Date(x.at).getDate()===i+1);return `<div class="calendar-day"><strong>${i+1}</strong><small>${n.length?n.length+' sessão(ões)':''}</small></div>`;}).join('')}</div><div class="cards" style="margin-top:20px">${a.map(x=>`<article class="card"><span class="badge">${({planned:'Planejado',done:'Realizado',missed:'Falta',cancelled:'Cancelado'})[x.status]}</span><h2>${E(x.title)}</h2><p>${E(state().students.find(s=>s.id===x.studentId)?.name||'Pessoal')}<br>${new Date(x.at).toLocaleString('pt-BR')}</p><div class="actions">${B('Editar','edit-appointment','secondary',attrs(x.id))}${B('Lembrete no aparelho','remind','text-button',attrs(x.id))}</div></article>`).join('')||empty('Nenhum compromisso no período.')}</div>`;}
function appointmentForm(x){C.form(x?'Editar compromisso':'Novo compromisso','b:appointment',`${I('title','Título',x?.title||'Sessão de treino','text','required minlength="2" maxlength="100"')}${S('studentId','Aluno',studentOptions(),x?.studentId||studentId)}${I('at','Data e hora',x?localDateTime(x.at):localDateTime(Date.now()+86400000),'datetime-local','required')}${S('status','Situação',[['planned','Planejado'],['done','Realizado'],['missed','Falta'],['cancelled','Cancelado']],x?.status||'planned')}${S('remindMinutes','Antecedência do lembrete',[[0,'Na hora'],[30,'30 minutos'],[60,'1 hora'],[1440,'1 dia']],x?.remindMinutes??60)}${!x?I('repeat','Repetir semanalmente (quantidade)',1,'number','required min="1" max="52"'):''}`,x?.id);}
const localDateTime=n=>{const d=new Date(n);return new Date(n-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
function assessments(){const data=state().advanced.assessments.filter(x=>!studentId||x.studentId===studentId).sort((a,b)=>b.at-a.at);return header('Avaliação e acompanhamento','Medidas e hábitos com registros independentes.',B('Nova avaliação','new-assessment','primary'))+chooseStudent()+`<div class="cards">${data.map(x=>`<article class="card"><h2>${E(state().students.find(s=>s.id===x.studentId)?.name)}</h2><p>${new Date(x.at).toLocaleDateString('pt-BR')}</p><dl><dt>Peso</dt><dd>${x.weight??'—'} kg</dd><dt>Altura</dt><dd>${x.height??'—'} cm</dd><dt>Cintura</dt><dd>${x.waist??'—'} cm</dd><dt>Gordura informada</dt><dd>${x.bodyFat??'—'}%</dd><dt>Energia / sono</dt><dd>${x.energy}/5 · ${x.sleep}/5</dd></dl>${x.photo?`<img class="assessment-photo" src="${E(x.photo)}" alt="Foto da avaliação autorizada pelo aluno">`:''}<p>${E(x.notes)}</p><p>Hábitos: ${E(x.habits||'Não informados')}</p>${B('Editar registro','edit-assessment','secondary',attrs(x.id))}</article>`).join('')||empty('Nenhuma avaliação registrada. Campos de medidas são opcionais.')}</div>`;}
function assessmentForm(x){studentRequired();C.form(x?'Editar avaliação':'Nova avaliação','b:assessment',`${S('studentId','Aluno',studentOptions(false),x?.studentId||studentId)}${I('at','Data',x?new Date(x.at).toISOString().slice(0,10):new Date().toISOString().slice(0,10),'date','required')}<div class="form-grid">${I('weight','Peso (kg)',x?.weight??'','number','min="1" max="500" step="any"')}${I('height','Altura (cm)',x?.height??'','number','min="30" max="250" step="any"')}${I('waist','Cintura (cm)',x?.waist??'','number','min="10" max="300" step="any"')}${I('bodyFat','Gordura corporal informada (%)',x?.bodyFat??'','number','min="0" max="80" step="any"')}${S('energy','Energia percebida',[1,2,3,4,5].map(n=>[n,n+'/5']),x?.energy||3)}${S('sleep','Qualidade do sono',[1,2,3,4,5].map(n=>[n,n+'/5']),x?.sleep||3)}</div>${T('habits','Hábitos e questionário livre',x?.habits||'')}${T('notes','Observações',x?.notes||'',2000)}<label>Foto (JPG/PNG/WebP, até 1 MB)<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label><label class="check-label"><input name="consent" type="checkbox" ${x?.consent?'checked':''}> Consentimento para armazenar a foto neste dispositivo e nos backups</label>${I('reeval','Agendar reavaliação (opcional)','','date')}`,x?.id);}
function planning(){const plans=state().advanced.plans.filter(x=>!studentId||x.studentId===studentId);return header('Periodização e planejamento','Mesociclos compostos por semanas editáveis.',B('Novo mesociclo','new-plan','primary'))+chooseStudent()+`<div class="cards">${plans.map(p=>{const elapsed=Math.floor((Date.now()-new Date(p.start+'T00:00:00').getTime())/604800000)+1;return `<article class="card"><span class="badge">${p.archived?'Arquivado':elapsed<1?'Ainda não iniciado':elapsed>p.weeks.length?'Período encerrado':`Semana atual: ${elapsed}/${p.weeks.length}`}</span><h2>${E(p.title)}</h2><p>${E(state().students.find(s=>s.id===p.studentId)?.name||'Pessoal')} · ${p.start}<br>${p.weeks.length} semanas</p>${p.weeks.map((w,i)=>{const completed=state().sessions.filter(s=>s.finishedAt&&w.applied.includes(s.routineId)).length;return `<div class="routine-row"><div><strong>Semana ${i+1} · ${w.kind==='DELOAD'?'Deload':w.kind==='RECOVERY'?'Recuperação':'Estímulo'}</strong><small>Volume ${w.volume}% · carga ${w.load}%<br>${w.applied.length} fichas aplicadas · ${completed} sessões concluídas</small></div><div>${B('Editar','edit-week','text-button',`${attrs(p.id)} data-index="${i}" ${w.applied.length?'disabled':''}`)}${B(w.applied.length?'Aplicada':'Aplicar','apply-week','secondary',`${attrs(p.id)} data-index="${i}" ${w.applied.length||p.archived?'disabled':''}`)}</div></div>`;}).join('')}<div class="actions">${B(p.archived?'Restaurar':'Arquivar','archive-plan','secondary',attrs(p.id))}</div></article>`;}).join('')||empty('Crie um mesociclo a partir das fichas existentes. A aplicação cria cópias independentes, após confirmação.')}</div>`;}
function planForm(){const routines=state().routines.filter(r=>!r.archived&&(!r.studentId||r.studentId===studentId));if(!routines.length)throw new Error('Crie uma ficha com exercícios antes de planejar.');C.form('Novo mesociclo','b:plan',`${I('title','Nome do mesociclo','','text','required minlength="2" maxlength="60"')}${S('studentId','Aluno',studentOptions(),studentId)}${I('start','Início',new Date().toISOString().slice(0,10),'date','required')}${I('weeks','Semanas',4,'number','required min="1" max="52"')}${S('model','Modelo',[['LINEAR','Linear'],['WAVE','Ondulatório'],['CUSTOM','Personalizado']],'LINEAR')}<fieldset><legend>Fichas de referência</legend>${routines.map(r=>`<label class="check-label"><input name="routineIds" type="checkbox" value="${E(r.id)}"> ${E(r.title)}</label>`).join('')}</fieldset><p class="note">Os modelos propõem fatores semanais editáveis, com deload a cada quarta semana. Revise cada semana antes de aplicar. A ficha original é preservada.</p>`);}
function muscle(){const data=muscleVolume(state(),studentId||null);return header('Volume e recuperação','Distribuição dos estímulos nos últimos sete dias.')+chooseStudent()+`<form data-kind="b:recovery" class="toolbar">${I('hours','Intervalo de referência (horas)',state().advanced.preferences.recoveryHours,'number','required min="12" max="168"')}<button class="secondary">Salvar referência</button></form><p class="note">Séries indiretas dependem dos músculos secundários informados no cadastro do exercício. O intervalo é uma referência configurável; o indicador não mede recuperação fisiológica.</p><div class="cards">${data.map(g=>`<article class="card"><h2>${E(g.muscle)}</h2><dl><dt>Séries diretas</dt><dd>${g.direct}</dd><dt>Indiretas</dt><dd>${g.indirect}</dd><dt>Dias com estímulo</dt><dd>${g.days.length}</dd><dt>Último estímulo</dt><dd>${new Date(g.last).toLocaleString('pt-BR')}</dd><dt>Fadiga relatada</dt><dd>${g.fatigue??'Não informada'}</dd></dl><p>${g.status}</p><small>${g.days.join(' · ')}</small></article>`).join('')||empty('Conclua sessões para ver a distribuição muscular.')}</div>`;}
function chart(title,points,key){const shown=points.slice(-12),max=Math.max(1,...shown.map(x=>x[key]));return `<section class="panel"><h3>${title}</h3><div class="bar-chart" aria-label="${title}">${shown.map(p=>`<div><span style="height:${Math.max(2,p[key]/max*100)}px"></span><small>${fmt(p[key])}</small></div>`).join('')}</div><small>Últimas 12 sessões · valores em kg${key==='volume'?' × rep.':''}</small></section>`;}
function analysis(){const ex=state().exercises.filter(e=>state().sessions.some(x=>x.studentId===(studentId||null)&&x.finishedAt&&x.items.some(i=>i.exerciseId===e.id)));const chosen=ex.find(e=>e.id===exerciseId)||ex[0];const result=chosen?performance(state(),studentId||null,chosen.id):null;return header('Análise e progressão','Resultados por aluno e exercício, sem alterar cargas automaticamente.')+chooseStudent()+`<form data-kind="b:exercise-filter" class="toolbar">${S('exerciseId','Exercício',ex.map(e=>[e.id,e.name]),chosen?.id)}<button class="secondary">Analisar</button></form>${result?`<div class="cards">${chart('Volume por sessão',result.points,'volume')}${chart('Carga máxima',result.points,'load')}${chart('1RM estimada (séries de 1–10 rep.)',result.points,'e1rm')}</div><div class="note"><h3>${result.action}</h3><p>${result.reason}</p>${result.suggested!==null?`<p>Referência: ${fmt(result.suggested)} kg. Edite a prescrição para aplicar uma decisão.</p>`:''}</div>`:empty('Ainda sem sessões concluídas para análise.')}`;}
function messages(){const selected=studentId||state().students[0]?.id;return header('Comunicação e feedback','Troca local e compartilhamento por pacotes criptografados.')+chooseStudent()+card('Conversas',`${state().advanced.messages.filter(m=>m.studentId===selected).sort((a,b)=>a.at-b.at).map(m=>`<div class="note ${m.sender==='student'?'subtle':''}"><strong>${m.sender==='student'?'Aluno':'Profissional'}</strong><small> · ${new Date(m.at).toLocaleString('pt-BR')}</small><p>${E(m.text)}</p></div>`).join('')||'<p class="muted">Sem mensagens neste aluno.</p>'}<form data-kind="b:message">${S('studentId','Aluno',studentOptions(false),selected)}${T('text','Mensagem ou feedback','',2000)}<button class="primary">Salvar mensagem</button></form>`)+`<div class="note">A troca entre aparelhos usa arquivos protegidos por senha. Não há servidor de mensagens ou sincronização automática nesta versão beta.</div><div class="actions">${B('Preparar pacote do aluno','share-student','primary')}${B('Importar retorno do aluno','import-feedback','secondary')}<a class="secondary" href="./student.html" target="_blank" rel="noopener">Abrir espaço do aluno</a></div>`;}
function finance(){const payments=state().advanced.payments.filter(p=>(!studentId||p.studentId===studentId)&&p.month===month),paid=payments.filter(p=>p.status==='paid').reduce((n,p)=>n+p.amountCents,0),pending=payments.filter(p=>p.status==='pending').reduce((n,p)=>n+p.amountCents,0);return header('Gestão profissional','Mensalidades e acompanhamento local de recebimentos.',B('Nova mensalidade','new-payment','primary'))+chooseStudent()+`<form data-kind="b:month" class="toolbar">${I('month','Competência',month,'month','required')}<button class="secondary">Mostrar</button></form><div class="metrics"><div class="metric"><div><b>${money(paid)}</b><span>Recebido</span></div></div><div class="metric"><div><b>${money(pending)}</b><span>Pendente</span></div></div></div><div class="actions" style="margin-bottom:20px">${B('Ocultar / mostrar valores','hide-money','secondary')}${B('Imprimir relatório / PDF','print-finance','secondary')}${B('Exportar CSV','export-finance','secondary')}</div><div class="cards">${payments.map(p=>`<article class="card"><h2>${E(state().students.find(x=>x.id===p.studentId)?.name)}</h2><p>${p.month} · ${p.status==='paid'?'Pago':'Pendente'}</p><h2>${money(p.amountCents)}</h2><p>${E(p.notes)}</p>${B('Editar mensalidade','edit-payment','secondary',attrs(p.id))}</article>`).join('')||empty('Nenhuma mensalidade nesta competência.')}</div>`;}
function paymentForm(x){studentRequired();C.form(x?'Editar mensalidade':'Nova mensalidade','b:payment',`${S('studentId','Aluno',studentOptions(false),x?.studentId||studentId)}${I('month','Competência',x?.month||month,'month','required')}${I('amount','Valor (R$)',x?x.amountCents/100:'','number','required min="0" max="1000000" step="0.01"')}${S('status','Situação',[['pending','Pendente'],['paid','Pago']],x?.status||'pending')}${T('notes','Observações',x?.notes||'')}`,x?.id);}
function quality(){const source=state().exercises.filter(x=>x.origin==='MD500');const approved=state().advanced.reviews.filter(r=>r.status==='approved').length;return header('Qualidade e biblioteca','Catálogo canônico e revisão explícita das mídias.')+`<div class="metrics"><div class="metric"><div><b>${source.length}/500</b><span>Exercícios importados</span></div></div><div class="metric"><div><b>${approved}</b><span>Revisões locais aprovadas</span></div></div></div><p class="note">O inventário de origem consultado registra 445 vínculos, 55 ausências e 155 revisões visuais pendentes. Esses números são uma fotografia do arquivo de origem, não aprovação das animações.</p><div class="actions">${B('Importar catálogo de 500 exercícios','import-catalog','primary')}${B('Verificar integridade local','integrity','secondary')}</div><div class="cards" style="margin-top:20px">${source.filter(x=>x.media?.pending||!x.media?.path).slice(0,30).map(e=>`<article class="card"><h3>${E(e.name)}</h3><p>${E(e.media?.review||'Mídia pendente')}</p>${B('Registrar revisão','review-media','secondary',attrs(e.id))}</article>`).join('')}</div><p class="footer-note">A importação do catálogo é idempotente por ID MD500 e evita duplicação de nomes equivalentes. Não baixa nem gera animações. A exibição de mídia externa será liberada somente após vínculo e aprovação verificados.</p>`;}
function portal(){const profile=state().profile;return header('Espaço do aluno',`Olá, ${E(profile?.name||'aluno')}.`)+card('Minha ficha',state().routines.filter(r=>!r.archived).map(r=>`<div class="routine-row"><div><strong>${E(r.title)}</strong><small>${r.items.length} exercícios</small></div>${C.button('Abrir treino','open-routine','primary',attrs(r.id))}</div>`).join('')||empty('Importe um pacote enviado pelo profissional.'))+card('Meu feedback',`<form data-kind="b:message"><input name="studentId" type="hidden" value="${E(profile.studentId)}">${T('text','Como foi o treino?','',2000)}<button class="primary">Salvar feedback</button></form>${state().advanced.messages.map(m=>`<p><strong>${m.sender==='student'?'Você':'Profissional'}:</strong> ${E(m.text)}</p>`).join('')}`)+`<div class="actions" style="margin-top:20px">${C.button('Exportar retorno criptografado','export','primary')}${C.button('Importar pacote atualizado','restore','secondary')}</div>`;}
export const betaViews={agenda,assessments,planning,muscle,analysis,messages,finance,quality,portal};
export async function betaClick(d){const cmd=d.cmd.slice(2),s=state();if(cmd==='modules'){modules();return;}if(cmd==='view'){C.done(d.view);return;}if(cmd==='new-appointment'){appointmentForm();return;}if(cmd==='edit-appointment'){appointmentForm(s.advanced.appointments.find(x=>x.id===d.id));return;}if(cmd==='new-assessment'){assessmentForm();return;}if(cmd==='edit-assessment'){assessmentForm(s.advanced.assessments.find(x=>x.id===d.id));return;}if(cmd==='new-payment'){paymentForm();return;}if(cmd==='edit-payment'){paymentForm(s.advanced.payments.find(x=>x.id===d.id));return;}if(cmd==='new-plan'){planForm();return;}if(cmd==='edit-week'){const p=s.advanced.plans.find(p=>p.id===d.id),w=p.weeks[Number(d.index)];if(w.applied.length)throw new Error('A semana já foi aplicada.');C.form('Editar semana','b:week',`<input name="index" type="hidden" value="${d.index}">${S('kind','Tipo',[['NORMAL','Estímulo'],['DELOAD','Deload'],['RECOVERY','Recuperação']],w.kind)}${I('volume','Volume relativo (%)',w.volume,'number','required min="10" max="200"')}${I('load','Carga relativa (%)',w.load,'number','required min="10" max="150"')}`,p.id);return;}
 if(cmd==='apply-week'){if(!confirm('Aplicar esta semana em cópias independentes? Revise o planejamento antes de confirmar.'))return;await C.commit(x=>applyWeek(x,d.id,Number(d.index)));C.render();C.toast('Semana aplicada. Acesse Treinos para abrir as fichas.');return;}
 if(cmd==='archive-plan'){await C.commit(x=>{const p=x.advanced.plans.find(p=>p.id===d.id);p.archived=!p.archived;});C.render();return;}
 if(cmd==='hide-money'){await C.commit(x=>{x.advanced.preferences.hideMoney=!x.advanced.preferences.hideMoney;});C.render();return;}
 if(cmd==='print-finance'){window.print();return;}if(cmd==='export-finance'){const rows=[['Aluno','Competência','Valor em centavos','Situação'],...s.advanced.payments.filter(p=>p.month===month&&(!studentId||p.studentId===studentId)).map(p=>[s.students.find(x=>x.id===p.studentId)?.name,p.month,p.amountCents,p.status])];await C.download('EvoluPersonal-mensalidades.csv',rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""').replace(/^[=+@-]/,"'")+'"').join(';')).join('\n'),'text/csv');return;}
 if(cmd==='remind'){const x=s.advanced.appointments.find(x=>x.id===d.id),at=x.at-x.remindMinutes*60000;if(at<=Date.now())throw new Error('O horário do lembrete já passou.');if(window.NativeBridge?.isNative){await window.NativeBridge.schedule(Math.abs(hash(x.id))%2000000000,x.title,'Compromisso na agenda do EvoluPersonal',at);C.toast('Lembrete agendado no aparelho.');}else{C.toast('Lembretes com o aplicativo fechado estão disponíveis no APK. No navegador, consulte a agenda ao abrir o app.');}return;}
 if(cmd==='import-catalog'){const response=await fetch('./catalog.json');if(!response.ok)throw new Error('Catálogo indisponível.');const catalog=await response.json();if(catalog.count!==500||catalog.exercises.length!==500||new Set(catalog.exercises.map(x=>x.id)).size!==500)throw new Error('Catálogo incompleto.');let added=0;await C.commit(x=>{for(const e of catalog.exercises){const existing=x.exercises.find(t=>t.id===e.id||normalize(t.name)===normalize(e.name));if(existing){if(!existing.externalId)Object.assign(existing,{externalId:e.externalId,origin:'MD500',media:e.media});}else{x.exercises.push(e);added++;}}});C.render();C.toast(`${added} exercícios incluídos; vínculos existentes preservados.`);return;}
 if(cmd==='integrity'){validate(s);C.toast('Estrutura, IDs, vínculos e limites locais válidos.');return;}
 if(cmd==='review-media'){C.form('Registrar revisão de correspondência','b:review',`${S('status','Resultado',[['pending','Pendente'],['approved','Aprovada após revisão'],['rejected','Reprovada']],'pending')}${T('note','Evidência e observações','')}`,d.id);return;}
 if(cmd==='share-student'){studentRequired();C.form('Compartilhar com o aluno','b:share',`${S('studentId','Aluno',studentOptions(false),studentId)}${I('password','Senha do pacote','','password','required minlength="8"')}<p class="note">Inclui somente cadastro deste aluno, fichas, exercícios usados, sessões, agenda e mensagens. Exclui dados financeiros, avaliações/fotos e os demais alunos. Compartilhe o arquivo e a senha apenas com o destinatário correto.</p>`);return;}
 if(cmd==='import-feedback'){C.form('Importar retorno do aluno','b:feedback','<label>Pacote de retorno<input name="file" type="file" accept=".evp,application/json" required></label>'+I('password','Senha','','password','required minlength="8"'));return;}
}
const hash=text=>{let h=0;for(const c of text)h=((h<<5)-h+c.charCodeAt(0))|0;return h;};
export async function betaSubmit(f,d){const kind=f.dataset.kind.slice(2),s=state();if(kind==='filter'){studentId=d.studentId;exerciseId='';C.done();return;}if(kind==='month'){month=d.month;C.done();return;}if(kind==='exercise-filter'){exerciseId=d.exerciseId;C.done();return;}
 if(kind==='appointment'){const at=new Date(d.at).getTime(),old=s.advanced.appointments.find(x=>x.id===f.dataset.id),repeat=old?1:Number(d.repeat);await C.commit(x=>{for(let i=0;i<repeat;i++){const record={id:old?.id||id(),title:d.title.trim(),studentId:d.studentId||null,at:at+i*604800000,status:d.status,remindMinutes:Number(d.remindMinutes)};if(old)Object.assign(x.advanced.appointments.find(a=>a.id===old.id),record);else x.advanced.appointments.push(record);}});C.done();return;}
 if(kind==='assessment'){const old=s.advanced.assessments.find(x=>x.id===f.dataset.id);let photo=old?.photo||null;const file=f.querySelector('[name=photo]').files[0];if(file){if(file.size>1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Use JPG/PNG/WebP de até 1 MB.');photo=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});}if(!d.consent)photo=null;const optional=k=>d[k]===''?null:Number(d[k]);await C.commit(x=>{const record={id:old?.id||id(),studentId:d.studentId,at:new Date(d.at+'T12:00:00').getTime(),weight:optional('weight'),height:optional('height'),waist:optional('waist'),bodyFat:optional('bodyFat'),photo,consent:!!d.consent,notes:d.notes.trim(),habits:d.habits.trim(),energy:Number(d.energy),sleep:Number(d.sleep)};if(old)Object.assign(x.advanced.assessments.find(a=>a.id===old.id),record);else x.advanced.assessments.push(record);if(d.reeval)x.advanced.appointments.push({id:id(),studentId:d.studentId,title:'Reavaliação',at:new Date(d.reeval+'T09:00:00').getTime(),status:'planned',remindMinutes:1440});});C.done();return;}
 if(kind==='payment'){const record={id:f.dataset.id||id(),studentId:d.studentId,month:d.month,amountCents:Math.round(Number(d.amount)*100),status:d.status,notes:d.notes.trim()};await C.commit(x=>{const old=x.advanced.payments.find(p=>p.id===record.id);if(old)Object.assign(old,record);else x.advanced.payments.push(record);});C.done();return;}
 if(kind==='message'){await C.commit(x=>{x.advanced.messages.push({id:id(),studentId:d.studentId,sender:x.profile.role==='student'?'student':'professional',text:d.text.trim(),at:Date.now()});});C.done();return;}
 if(kind==='plan'){const ids=new FormData(f).getAll('routineIds');if(!ids.length)throw new Error('Selecione ao menos uma ficha.');await C.commit(x=>{x.advanced.plans.push({id:id(),title:d.title.trim(),studentId:d.studentId||null,start:d.start,model:d.model,weeks:createWeeks(ids,Number(d.weeks),d.model),archived:false});});C.done();return;}
 if(kind==='week'){await C.commit(x=>{const w=x.advanced.plans.find(p=>p.id===f.dataset.id).weeks[Number(d.index)];if(w.applied.length)throw new Error('Semana já aplicada.');Object.assign(w,{kind:d.kind,volume:Number(d.volume),load:Number(d.load)});});C.done();return;}
 if(kind==='recovery'){await C.commit(x=>{x.advanced.preferences.recoveryHours=Number(d.hours);});C.done();return;}
 if(kind==='review'){await C.commit(x=>{const record={id:f.dataset.id,status:d.status,note:d.note.trim()};const old=x.advanced.reviews.find(r=>r.id===record.id);if(old)Object.assign(old,record);else x.advanced.reviews.push(record);});C.done();return;}
 if(kind==='share'){const packet=validate(studentBundle(s,d.studentId));await C.download(`EvoluPersonal-aluno-${d.studentId}.evp`,await exportBackup(packet,d.password));C.done();C.toast('Pacote do aluno preparado.');return;}
 if(kind==='feedback'){const file=f.querySelector('[name=file]').files[0];if(!file||file.size>10*1024*1024)throw new Error('Selecione um pacote de até 10 MB.');const packet=await importBackup(await file.text(),d.password);if(!confirm(`Importar novas sessões e mensagens de ${packet.profile.name}? Dados existentes não serão substituídos.`))return;await C.commit(x=>mergeStudentFeedback(x,packet));C.done();C.toast('Retorno importado sem substituir o histórico.');return;}
}
